const titles = $json.title ?? [];
const links = $json.link ?? [];
const dates = $json.pubDate ?? [];
const contents = $json.content ?? [];

const count = titles.length;

const escapeHtml = (value = '') =>
  String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');

const stripHtml = (html = '') =>
  String(html)
    .replace(/<style[^>]*>[\\s\\S]*?<\\/style>/gi, '')
    .replace(/<script[^>]*>[\\s\\S]*?<\\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\\s+/g, ' ')
    .trim();

const truncate = (text, max = 240) => {
  const clean = stripHtml(text);
  if (clean.length <= max) return clean;
  return clean.slice(0, max).trim() + '…';
};

const formatDate = (date) => {
  try {
    return new Intl.DateTimeFormat('fr-FR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    }).format(new Date(date));
  } catch {
    return '';
  }
};

const getSource = (url = '') => {
  const value = String(url).toLowerCase();

  if (value.includes('cert.ssi.gouv.fr')) return 'CERT-FR';
  if (value.includes('thehackernews.com')) return 'The Hacker News';
  if (value.includes('ausha.co')) return 'Riskintel Media';

  try {
    return new URL(url).hostname.replace(/^www\\./, '');
  } catch {
    return 'Source';
  }
};

const articleCards = titles.map((title, i) => {
  const safeTitle = escapeHtml(title);
  const safeLink = escapeHtml(links[i] ?? '#');
  const safeContent = escapeHtml(truncate(contents[i] ?? ''));
